static void merge_sort(int *a, int *tmp, size_t n, int depth) {
    if (n < 1024 || depth == 0) { insertion_sort(a, n); return; }   /* base case */
    size_t m = n / 2;
    merge_sort(a, tmp, m, depth - 1);          /* left half in this thread  */
    merge_sort(a + m, tmp + m, n - m, depth - 1);  /* or spawn+join here */
    merge(a, m, a + m, n - m, tmp);            /* combine */
}
